-- Reaplica, apos um reset/reimport do banco de dev, a exclusao em lote feita manualmente na
-- tela "Nao localizada na adquirente" (motivo UNDONE) em 2026-07-31 entre 12:37 e 12:45.
-- Sem isso, um reset do banco de dev perde esse trabalho manual e as 391 vendas ERP abaixo
-- voltam a aparecer como pendentes de conciliacao.
--
-- Mesma logica de ConciliationWaitingService.markErpAsDeletedMissingAcquirer():
--   status_transaction         = 4 (StatusTransactionEnum.DELETED)
--   status_transaction_reason  = 2 (StatusTransactionReasonEnum.CV_NOT_FOUND_ADQ)
--   reason_exclusion_status    = 2 (StatusTransactionReasonExclusionEnum.UNDONE)
--   observations                append da mesma mensagem gerada por buildDeletionObservation()
--
-- Casa por (nsu, "authorization", sale_date) em vez do id: o id (UUID) muda a cada reimport,
-- mas esses 3 campos sao estaveis desde que o arquivo ERP de origem seja o mesmo. sale_date
-- entra na chave porque nsu+authorization sozinhos NAO sao unicos o suficiente aqui: 7 pares
-- se repetem no lote (mesma autorizacao usada em vendas diferentes) e ha 3 outras vendas na
-- base, fora do lote, que reaproveitam nsu+authorization de placeholders de teste
-- (ex.: authorization='123456') - so nsu+authorization bateria errado nessas.
--
-- Uso: depois de resetar/reimportar o banco de dev, rode com psql:
--   psql -h 127.0.0.1 -p 5432 -U postgres -d cardsync -f reapply-erp-missing-acquirer-exclusions.sql
-- ou use o wrapper reapply-erp-missing-acquirer-exclusions.ps1 (mesmos defaults do application-dev.yml).

UPDATE cs_transaction_erp e
SET
  deleted_date = now(),
  status_transaction = 4,
  status_transaction_reason = 2,
  reason_exclusion_status = 2,
  observations = CASE
    WHEN e.observations IS NULL OR e.observations = '' THEN 'Venda marcada como excluída porque não foi localizada na adquirente. Motivo: UNDONE.'
    ELSE e.observations || ' | ' || 'Venda marcada como excluída porque não foi localizada na adquirente. Motivo: UNDONE.'
  END
WHERE (e.nsu, e."authorization", e.sale_date) IN (
